diff --git a/tools/releasecheck/release_test.go b/tools/releasecheck/release_test.go
index 6c872ac3..5d1d3260 100644
--- a/tools/releasecheck/release_test.go
+++ b/tools/releasecheck/release_test.go
@@ -1,13 +1,16 @@
 package releasecheck

 import (
+	"fmt"
 	"os"
 	"os/exec"
 	"path/filepath"
 	"regexp"
 	"runtime"
+	"strconv"
 	"strings"
 	"testing"
